package com.sigo.asistencia.controller; import com.sigo.asistencia.entity.Trabajador; import com.sigo.asistencia.exception.ResourceNotFoundException; import com.sigo.asistencia.repository.TrabajadorRepository; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/trabajadores") @RequiredArgsConstructor public class TrabajadorController{private final TrabajadorRepository r;@GetMapping public List<Trabajador> listar(@RequestParam(required=false)String puesto){return puesto==null||puesto.isBlank()?r.findByActivoTrueOrderByNombreCompletoAsc():r.findByPuestoNombreIgnoreCaseAndActivoTrueOrderByNombreCompletoAsc(puesto);}@GetMapping("/{id}") public Trabajador obtener(@PathVariable Long id){return r.findById(id).orElseThrow(()->new ResourceNotFoundException("Trabajador no encontrado"));}@GetMapping("/codigo/{codigo}") public Trabajador codigo(@PathVariable Integer codigo){return r.findByCodigo(codigo).orElseThrow(()->new ResourceNotFoundException("Trabajador no encontrado"));}}
